\title{Affine Rerandomization, Noise Budgets, and\\Quarter-Modulus Decoding in Learning with Errors}
\author{Aristotle}
\date{July 25, 2026}
\begin{document}
\maketitle

\begin{abstract}
We develop algebraic and analytic results underlying elementary search-to-decision and correctness arguments for Learning with Errors cryptography. Over a prime residue field, every affine transformation $x\mapsto ax+b$ with $a\ne0$ is a bijection and therefore preserves uniformity and finite sums. Bounded additive errors accumulate at most linearly. For binary centers $0$ and $q/2$, perturbations of magnitude strictly below $q/4$ remain decodable, while two independently perturbed codewords retain positive separation. A hybrid decomposition across $n$ coordinates guarantees a coordinate gap of at least one $n$th of the total advantage. These facts yield an additive modulus-switching budget, an independent-repetition amplification formula, and a modulus--noise tradeoff. Particular attention is paid to positivity and strictness assumptions at decoding boundaries.
\end{abstract}

\section{Introduction}
Learning with Errors (LWE) replaces exact linear equations over a finite residue system by equations containing small additive disturbances. A sample consists schematically of a public vector $a$ and a value resembling $\langle a,s\rangle+e$ modulo a modulus, where $s$ is secret and $e$ is small. Error obstructs direct recovery while legitimate operations preserve enough separation to decode.

Two kinds of reasoning recur. Exact finite algebra shows that nonzero scaling and translation over a prime field are permutations, so affine rerandomization introduces no bias. Quantitative analysis uses triangle inequalities for noise, interval inequalities for decoding, and averaging for coordinatewise hybrid arguments. We assemble these components and state every necessary hypothesis explicitly. In particular, $q>0$ is indispensable when $q/4$ is treated as an error radius or when inequalities are multiplied by $q$.

\section{Affine algebra over a prime residue field}
Let $p$ be prime and let $\mathbb Z_p$ denote the field of residues modulo $p$.
\begin{definition}
For $a,b\in\mathbb Z_p$, the affine map $A_{a,b}:\mathbb Z_p\to\mathbb Z_p$ is
\[
A_{a,b}(x)=ax+b.
\]
\end{definition}

\begin{theorem}[Nonzero multiplication]
If $a\in\mathbb Z_p$ is nonzero, then $x\mapsto ax$ is a bijection of $\mathbb Z_p$.
\end{theorem}
\begin{proof}[Proof sketch]
The inverse is $y\mapsto a^{-1}y$, which exists because $\mathbb Z_p$ is a field.
\end{proof}

\begin{theorem}[Affine permutation theorem]
If $a\ne0$, then $A_{a,b}$ is bijective, with
\[
A_{a,b}^{-1}(y)=a^{-1}(y-b).
\]
\end{theorem}
\begin{proof}[Proof sketch]
Nonzero multiplication is bijective, as is translation by $b$. Compose their inverses, or verify the displayed formula by substitution.
\end{proof}

\begin{proposition}[Composition law]
For arbitrary coefficients,
\[
A_{a_1,b_1}\circ A_{a_2,b_2}=A_{a_1a_2,\,a_1b_2+b_1}.
\]
\end{proposition}
\begin{proof}[Proof sketch]
Expand $a_1(a_2x+b_2)+b_1$ and apply distributivity.
\end{proof}

\begin{corollary}[Image, sum, and uniformity invariance]
If $a\ne0$, the affine image of $\mathbb Z_p$ is all of $\mathbb Z_p$. For every $f:\mathbb Z_p\to\mathbb R$,
\[
\sum_{x\in\mathbb Z_p}f(ax+b)=\sum_{y\in\mathbb Z_p}f(y).
\]
Consequently, if $X$ is uniform on $\mathbb Z_p$, then $aX+b$ is uniform.
\end{corollary}
\begin{proof}[Proof sketch]
Relabel the finite sum along the affine permutation. Every output has one preimage and hence probability $1/p$.
\end{proof}

\section{Deterministic noise accumulation}
\begin{theorem}[Full-family accumulation]
Let $e_1,\ldots,e_m$ be integers or real numbers satisfying $|e_i|\le B$. Then
\[
\left|\sum_{i=1}^{m}e_i\right|\le mB.
\]
\end{theorem}
\begin{proof}[Proof sketch]
The triangle inequality gives $|\sum_i e_i|\le\sum_i|e_i|\le\sum_iB=mB$.
\end{proof}

\begin{theorem}[Subset accumulation]
For $S\subseteq\{1,\ldots,m\}$ under the same individual bounds,
\[
\left|\sum_{i\in S}e_i\right|\le |S|B.
\]
\end{theorem}
\begin{proof}[Proof sketch]
Apply the preceding triangle-inequality argument only to indices in $S$.
\end{proof}

These are worst-case certificates and are sharp when all selected errors have the same sign and magnitude $B$. Random centered errors may exhibit cancellation, but correctness based on these bounds does not depend on it.

\section{Quarter-modulus decoding}
Let $q>0$. Encode a bit $\mu\in\{0,1\}$ at $c_\mu=\mu q/2$, so the centers are $0$ and $q/2$.

\begin{lemma}[Noisy zero interval]
If $|e|<q/4$, then
\[
-q/4<e<q/4.
\]
\end{lemma}
\begin{proof}[Proof sketch]
Use the defining order characterization of absolute value.
\end{proof}

\begin{theorem}[Noisy one interval]
If $q>0$ and $|e|<q/4$, then
\[
\frac q4<\frac q2+e<\frac{3q}{4}.
\]
\end{theorem}
\begin{proof}[Proof sketch]
Add $q/2$ to both sides of $-q/4<e<q/4$.
\end{proof}

\begin{theorem}[Positive separation]
If $q>0$, $|e|<q/4$, and $|e'|<q/4$, then
\[
\frac q2-|e|-|e'|>0.
\]
Thus perturbations of the zero and one codewords retain a positive gap.
\end{theorem}
\begin{proof}[Proof sketch]
Adding the two error bounds yields $|e|+|e'|<q/2$; rearrange.
\end{proof}

\begin{theorem}[Translation-invariant rounding correctness]
For $q>0$, $\mu\in\mathbb R$, and $|e|<q/4$,
\[
\left|\mu\frac q2+e-\mu\frac q2\right|<\frac q4.
\]
\end{theorem}
\begin{proof}[Proof sketch]
The center terms cancel, leaving $|e|$.
\end{proof}

Strictness excludes the tie at $|e|=q/4$, where a received point can be equidistant from the two centers.

\section{Coordinate advantage in a hybrid argument}
Let $g_i$ denote the contribution of coordinate $i$ to a hybrid decomposition.
\begin{theorem}[Coordinate advantage bound]
Let $n>0$, let $g_1,\ldots,g_n\in\mathbb R$, and suppose
\[
\varepsilon\le\sum_{i=1}^{n}g_i.
\]
Then some $i$ satisfies $g_i\ge\varepsilon/n$.
\end{theorem}
\begin{proof}[Proof sketch]
If all $g_i<\varepsilon/n$, then summing gives $\sum_i g_i<n(\varepsilon/n)=\varepsilon$, a contradiction.
\end{proof}

\begin{corollary}[Search signal from decision signal]
A decision gap of at least $\varepsilon$ decomposed across $n$ secret coordinates has a coordinate contribution at least $\varepsilon/n$.
\end{corollary}
\begin{proof}[Proof sketch]
Apply the theorem. For prime-modulus affine rerandomization, the affine permutation theorem supplies exact uniformity for transformed wrong guesses.
\end{proof}

\section{Modulus switching}
Suppose $|e_{\rm LWE}|\le B$ and $|r_i|\le\delta$ for $1\le i\le n$.
\begin{theorem}[Combined switching-noise bound]
\[
\left|e_{\rm LWE}+\sum_{i=1}^{n}r_i\right|\le B+n\delta.
\]
\end{theorem}
\begin{proof}[Proof sketch]
Use the two-term triangle inequality, bound the original error by $B$, and apply full-family accumulation to the rounding errors.
\end{proof}

\begin{corollary}[Correctness after switching]
If $B+n\delta<q/4$, then
\[
\left|e_{\rm LWE}+\sum_{i=1}^{n}r_i\right|<q/4,
\]
so the quarter-modulus decoding condition survives modulus switching.
\end{corollary}
\begin{proof}[Proof sketch]
Chain the combined weak bound with the strict parameter budget.
\end{proof}

\section{Amplification and parameter scaling}
\begin{theorem}[Independent success amplification]
For $0\le p\le1$ and an integer $k>0$, the probability of at least one success in $k$ independent trials of success probability $p$ is
\[
P_k=1-(1-p)^k,
\]
and $P_k\ge p$.
\end{theorem}
\begin{proof}[Proof sketch]
All trials fail with probability $(1-p)^k$. Since $0\le1-p\le1$ and $k\ge1$, $(1-p)^k\le1-p$.
\end{proof}

\begin{theorem}[Modulus--noise tradeoff]
For $n\ge0$ and $q>0$, if
\[
\frac{2\sqrt n}{q}\le\alpha,
\]
then $2\sqrt n\le\alpha q$.
\end{theorem}
\begin{proof}[Proof sketch]
Multiply by positive $q$, preserving the inequality direction. Division proves the converse as well.
\end{proof}

\section{Algorithms and complexity}
An \emph{affine uniformity audit} enumerates $(ax+b)\bmod p$ for all $x$ and checks that every residue appears once. It costs $O(p)$ time and $O(p)$ memory; for known prime $p$, the symbolic condition $a\not\equiv0\pmod p$ suffices.

A \emph{noise-budget certificate} computes $M=B+n\delta$ and accepts exactly when $M<q/4$. Summary-bound arithmetic is constant time; checking $n$ raw error bounds costs $O(n)$ time. A \emph{coordinate selector} verifies $\varepsilon\le\sum_i g_i$ and returns an index maximizing $g_i$ in $O(n)$ time and $O(1)$ auxiliary space. For $0<p<1$ and target failure $0<\eta<1$, a repetition planner chooses
\[
k=\left\lceil\frac{\log\eta}{\log(1-p)}\right\rceil.
\]
Then $(1-p)^k\le\eta$.

\section{Numerical examples}
For $p=17$, $a=5$, and $b=8$, the affine image is
\[
8,13,1,6,11,16,4,9,14,2,7,12,0,5,10,15,3,
\]
which contains every residue once. For $q=128$, the decoding radius is $32$. A noisy zero with error $19$ remains in the zero region, while a noisy one with error $-23$ is $64-23=41$, lying between $32$ and $96$.

If an original error is $4$ and four rounding errors are $0.5,-0.25,0.75,0.1$, each bounded by $0.75$, then the deterministic budget is $4+4(0.75)=7<32$; the realized signed error is $5.1$. For coordinate gaps $0.01,0.025,0.04,0.015$ and certified total $0.08$, the guaranteed threshold is $0.02$, while the maximum is $0.04$. Finally, success probability $0.18$ amplified across eight independent trials becomes $1-0.82^8\approx0.796$.

\section{Applications, limitations, and discussion}
The affine theorem extends to composite moduli only when $a$ is a unit; nonzero is insufficient there. The rounding theorems certify a scalar binary layer, not an entire encryption scheme or an error distribution. A complete search-to-decision reduction must also define its hybrids, establish their telescoping gap, implement coordinate tests, and analyze sampling cost. Likewise, independent amplification requires actual independence.

Worst-case accumulation is conservative but compositional. One component need only export $B$ or $\delta$ rather than reveal internal signs. Probabilistic assumptions could yield $\sqrt n$-scale high-probability bounds, whereas the present $n\delta$ certificate covers every admissible vector. Explicit positivity is equally structural: it makes $q/4$ a radius and permits multiplication or division without reversing inequalities.

\section{Future directions}
Natural cryptographic extensions include composite moduli, concentration bounds for random errors, complete coordinatewise reductions, and vector-valued modulus switching. Broader mathematical directions include the Courant--Fischer hierarchy, compact self-adjoint operator spectra, continuous and Borel functional calculi, projection-valued measures, and quantum notions of variance, uncertainty, commuting observables, and measurement probabilities.

\section{Conclusion}
Prime-field affine maps preserve exact uniformity; triangle inequalities bound accumulated noise; quarter-modulus intervals separate binary encodings; hybrid averaging locates a useful coordinate; and additive budgets protect decoding after switching. Independent repetition and explicit parameter scaling complete a compact toolkit. Every assumption has a visible role, and every resulting bound can be audited directly.
\end{document}

