from __future__ import annotations

def decoded_bit(bit: int, q: float, error: float) -> tuple[float, int]:
    if bit not in (0, 1) or q <= 0 or abs(error) >= q/4:
        raise ValueError("require bit, q > 0, and |error| < q/4")
    received = (bit*q/2 + error) % q
    d0 = min(received, q-received)
    d1 = abs(received-q/2)
    return received, 0 if d0 < d1 else 1

if __name__ == "__main__":
    for bit, error in [(0, 19.0), (1, -23.0)]:
        print(bit, error, decoded_bit(bit, 128.0, error))

from __future__ import annotations

def switching_certificate(q: float, B: float, n: int, delta: float) -> tuple[float, bool]:
    if q <= 0 or B < 0 or n < 0 or delta < 0:
        raise ValueError("invalid parameter")
    budget = B+n*delta
    return budget, budget < q/4

def amplified_probability(p: float, k: int) -> float:
    if not 0 <= p <= 1 or k <= 0:
        raise ValueError("invalid probability or repetition count")
    return 1-(1-p)**k

if __name__ == "__main__":
    print("switching:", switching_certificate(128, 4, 4, .75))
    print("amplified:", amplified_probability(.18, 8))

