from __future__ import annotations

def audit_affine_permutation(p: int, a: int, b: int) -> bool:
    if p <= 1 or a % p == 0:
        return False
    return len({(a*x+b) % p for x in range(p)}) == p

from __future__ import annotations

def certify_rounding(q: float, original_bound: float, dimension: int, rounding_bound: float) -> dict[str, float | bool]:
    if q <= 0 or original_bound < 0 or dimension < 0 or rounding_bound < 0:
        raise ValueError("q must be positive and all bounds nonnegative")
    total = original_bound + dimension*rounding_bound
    return {"total_bound": total, "radius": q/4, "certified": total < q/4}

from __future__ import annotations
from math import ceil, log
from typing import Sequence

def select_coordinate(total_gap: float, gaps: Sequence[float]) -> tuple[int, float]:
    if not gaps or sum(gaps) < total_gap:
        raise ValueError("the gap decomposition hypothesis fails")
    i = max(range(len(gaps)), key=gaps.__getitem__)
    assert gaps[i] + 1e-15 >= total_gap/len(gaps)
    return i, gaps[i]

def repetitions_for_failure(p: float, eta: float) -> int:
    if not 0 < p <= 1 or not 0 < eta < 1:
        raise ValueError("require 0 < p <= 1 and 0 < eta < 1")
    return 1 if p == 1 else ceil(log(eta)/log(1-p))

